steps.preRequestScript:
var moment = require("moment");
// Rota e passageiros das respostas do usuário (<<…>> = resposta; o create_flow_from_recipe troca sozinho):
pm.environment.set("flowOrigin", "<<route.origin>>");
pm.environment.set("flowDestination", "<<route.destination>>");
pm.environment.set("flowPaxCount", "<<pax.number>>");
// Data única por execução: evita o 409 Validate.Unblocked.Quote (cotação aberta na mesma rota+data).
pm.environment.set("flowQuoteDeparture", moment().add(60 + (Math.floor(moment().valueOf() / 1000) % 240), "days").format("YYYY-MM-DD"));
// Começa vazio: se o POST falhar, os passos seguintes não usam a cotação de outra execução.
pm.environment.set("quoteNumber", "");
pm.environment.set("quoteToken", "");

steps.postResponseScript:
var data = pm.response.json().data;
pm.environment.set("quoteNumber", data.number);
pm.environment.set("quoteToken", data.token);

// 1ª tarifa do 1º voo da oferta (mesma rota/data/pax da cotação).
var data = pm.response.json().data;
pm.environment.set("quoteId", data.offer.journeysAvailableByMarket[0].journeys[0].fares[0].quoteId);
